1	package main
2	
3	import (
4		"crypto/rand"
5		"encoding/hex"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"os"
10		"path/filepath"
11		"sort"
12		"strings"
13		"sync"
14		"time"
15	
16		// 内嵌时区数据库，保证在没有 /usr/share/zoneinfo 的环境中也能校验 IANA 时区。
17		_ "time/tzdata"
18	)
19	
20	// WeeklyHour 表示每周固定的一段开放时间。
21	// Weekday 用 1 到 7 表示周一至周日；Start/End 为 HH:mm。
22	// End 晚于 Start 表示当天结束，早于 Start 表示次日结束。
23	type WeeklyHour struct {
24		Weekday int    `json:"weekday"`
25		Start   string `json:"start"`
26		End     string `json:"end"`
27	}
28	
29	// Venue 是一条场地记录。
30	type Venue struct {
31		ID          string       `json:"id"`
32		Name        string       `json:"name"`
33		Capacity    int          `json:"capacity"`
34		Timezone    string       `json:"timezone"`
35		WeeklyHours []WeeklyHour `json:"weeklyHours"`
36	}
37	
38	// apiError 是返回给客户端的校验错误（HTTP 400）。
39	type apiError struct{ msg string }
40	
41	func (e *apiError) Error() string { return e.msg }
42	
43	func badRequest(format string, args ...any) error {
44		return &apiError{msg: fmt.Sprintf(format, args...)}
45	}
46	
47	// store 负责场地记录的持久化，所有访问都通过互斥锁串行化。
48	type store struct {
49		mu   sync.Mutex
50		path string
51	}
52	
53	func newStore(dataDir string) (*store, error) {
54		if err := os.MkdirAll(dataDir, 0700); err != nil {
55			return nil, err
56		}
57		path := filepath.Join(dataDir, "venues.json")
58		// 全新数据目录时初始化为空数组，保持原有行为。
59		file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
60		if err == nil {
61			if _, err := file.WriteString("[]\n"); err != nil {
62				_ = file.Close()
63				return nil, err
64			}
65			if err := file.Close(); err != nil {
66				return nil, err
67			}
68		} else if !errors.Is(err, os.ErrExist) {
69			return nil, err
70		}
71		return &store{path: path}, nil
72	}
73	
74	// load 读取并解析全部记录。读不到、JSON 损坏或结构异常都返回错误，
75	// 调用方必须按 500 处理，绝不能把错误数据当作空列表覆盖。
76	func (s *store) load() ([]Venue, error) {
77		raw, err := os.ReadFile(s.path)
78		if err != nil {
79			return nil, err
80		}
81		var venues []Venue
82		if err := json.Unmarshal(raw, &venues); err != nil {
83			return nil, fmt.Errorf("venues data is corrupted: %w", err)
84		}
85		if venues == nil {
86			venues = []Venue{}
87		}
88		for i := range venues {
89			if venues[i].WeeklyHours == nil {
90				venues[i].WeeklyHours = []WeeklyHour{}
91			}
92		}
93		return venues, nil
94	}
95	
96	// save 通过同目录临时文件 + 重命名原子写入，避免半写状态损坏数据。
97	func (s *store) save(venues []Venue) error {
98		encoded, err := json.MarshalIndent(venues, "", "  ")
99		if err != nil {
100			return err
101		}
102		encoded = append(encoded, '\n')
103		dir := filepath.Dir(s.path)
104		tmp, err := os.CreateTemp(dir, ".venues-*.tmp")
105		if err != nil {
106			return err
107		}
108		tmpName := tmp.Name()
109		defer os.Remove(tmpName)
110		if _, err := tmp.Write(encoded); err != nil {
111			_ = tmp.Close()
112			return err
113		}
114		if err := tmp.Close(); err != nil {
115			return err
116		}
117		if err := os.Chmod(tmpName, 0600); err != nil {
118			return err
119		}
120		return os.Rename(tmpName, s.path)
121	}
122	
123	// list 返回当前全部场地（按首次创建顺序保留）。
124	func (s *store) list() ([]Venue, error) {
125		s.mu.Lock()
126		defer s.mu.Unlock()
127		return s.load()
128	}
129	
130	// create 校验请求内容，通过后写入新记录并返回保存后的场地。
131	// 校验失败时返回 apiError（400），不会写入任何内容。
132	func (s *store) create(payload map[string]any) (Venue, error) {
133		s.mu.Lock()
134		defer s.mu.Unlock()
135	
136		venues, err := s.load()
137		if err != nil {
138			return Venue{}, err
139		}
140	
141		venue, err := buildVenue(payload)
142		if err != nil {
143			return Venue{}, err
144		}
145	
146		venue.ID = newID()
147		for idTaken(venues, venue.ID) {
148			// 极小概率的随机碰撞：重新生成直到唯一。
149			venue.ID = newID()
150		}
151		venues = append(venues, venue)
152		if err := s.save(venues); err != nil {
153			return Venue{}, err
154		}
155		return venue, nil
156	}
157	
158	// buildVenue 对请求对象做逐字段严格校验。
159	func buildVenue(payload map[string]any) (Venue, error) {
160		name, err := requireString(payload, "name")
161		if err != nil {
162			return Venue{}, err
163		}
164		name = strings.TrimSpace(name)
165		if name == "" {
166			return Venue{}, badRequest("name 去除首尾空白后不能为空")
167		}
168	
169		capacity, err := requirePositiveInt(payload, "capacity")
170		if err != nil {
171			return Venue{}, err
172		}
173	
174		timezone, err := requireString(payload, "timezone")
175		if err != nil {
176			return Venue{}, err
177		}
178		if timezone == "" || timezone == "Local" {
179			return Venue{}, badRequest("timezone 必须是有效的 IANA 时区名称，例如 Asia/Shanghai")
180		}
181		if _, err := time.LoadLocation(timezone); err != nil {
182			return Venue{}, badRequest("timezone 必须是有效的 IANA 时区名称，例如 Asia/Shanghai")
183		}
184	
185		rawHours, ok := payload["weeklyHours"]
186		if !ok {
187			return Venue{}, badRequest("缺少 weeklyHours 字段")
188		}
189		hours, err := parseWeeklyHours(rawHours)
190		if err != nil {
191			return Venue{}, err
192		}
193		if err := validateHours(hours); err != nil {
194			return Venue{}, err
195		}
196	
197		return Venue{
198			Name:        name,
199			Capacity:    capacity,
200			Timezone:    timezone,
201			WeeklyHours: hours,
202		}, nil
203	}
204	
205	func missingOrWrong(field, kind string) error {
206		return badRequest("%s 类型错误：应为%s", field, kind)
207	}
208	
209	func requireString(payload map[string]any, field string) (string, error) {
210		value, ok := payload[field]
211		if !ok || value == nil {
212			return "", missingOrWrong(field, "字符串")
213		}
214		str, ok := value.(string)
215		if !ok {
216			return "", missingOrWrong(field, "字符串")
217		}
218		return str, nil
219	}
220	
221	// jsonInt 取出一个 JSON 数字并要求它是整数；正数范围由调用方决定。
222	func jsonInt(value any) (int, bool) {
223		number, ok := value.(float64)
224		if !ok {
225			return 0, false
226		}
227		if number != float64(int64(number)) {
228			return 0, false
229		}
230		return int(number), true
231	}
232	
233	func requirePositiveInt(payload map[string]any, field string) (int, error) {
234		value, ok := payload[field]
235		if !ok || value == nil {
236			return 0, missingOrWrong(field, "正整数")
237		}
238		number, ok := jsonInt(value)
239		if !ok || number <= 0 {
240			return 0, missingOrWrong(field, "正整数")
241		}
242		return number, nil
243	}
244	
245	func parseWeeklyHours(raw any) ([]WeeklyHour, error) {
246		if raw == nil {
247			return nil, badRequest("weeklyHours 类型错误：应为数组")
248		}
249		items, ok := raw.([]any)
250		if !ok {
251			return nil, badRequest("weeklyHours 类型错误：应为数组")
252		}
253		hours := make([]WeeklyHour, 0, len(items))
254		for i, item := range items {
255			obj, ok := item.(map[string]any)
256			if !ok || obj == nil {
257				return nil, badRequest("weeklyHours[%d] 类型错误：应为对象", i)
258			}
259			rawWeekday, ok := obj["weekday"]
260			if !ok || rawWeekday == nil {
261				return nil, badRequest("weeklyHours[%d].weekday 类型错误：应为 1 到 7 的整数", i)
262			}
263			weekday, ok := jsonInt(rawWeekday)
264			if !ok {
265				return nil, badRequest("weeklyHours[%d].weekday 类型错误：应为 1 到 7 的整数", i)
266			}
267			if weekday < 1 || weekday > 7 {
268				return nil, badRequest("weeklyHours[%d].weekday 必须为 1 到 7（周一至周日）", i)
269			}
270			start, err := hourField(obj, i, "start")
271			if err != nil {
272				return nil, err
273			}
274			end, err := hourField(obj, i, "end")
275			if err != nil {
276				return nil, err
277			}
278			hours = append(hours, WeeklyHour{Weekday: weekday, Start: start, End: end})
279		}
280		return hours, nil
281	}
282	
283	func hourField(obj map[string]any, i int, field string) (string, error) {
284		value, ok := obj[field]
285		if !ok || value == nil {
286			return "", badRequest("weeklyHours[%d].%s 类型错误：应为 HH:mm 时间", i, field)
287		}
288		str, ok := value.(string)
289		if !ok || !validHHMM(str) {
290			return "", badRequest("weeklyHours[%d].%s 时间无效，必须为 00:00 至 23:59 的 HH:mm 格式", i, field)
291		}
292		return str, nil
293	}
294	
295	// validHHMM 严格校验 HH:mm：两位小时、冒号、两位分钟，范围 00:00–23:59。
296	func validHHMM(value string) bool {
297		if len(value) != 5 || value[2] != ':' {
298			return false
299		}
300		for i, c := range value {
301			if i == 2 {
302				continue
303			}
304			if c < '0' || c > '9' {
305				return false
306			}
307		}
308		hour := int(value[0]-'0')*10 + int(value[1]-'0')
309		minute := int(value[3]-'0')*10 + int(value[4]-'0')
310		return hour <= 23 && minute <= 59
311	}
312	
313	func minutes(value string) int {
314		return int(value[0]-'0')*600 + int(value[1]-'0')*60 +
315			int(value[3]-'0')*10 + int(value[4]-'0')
316	}
317	
318	// interval 是展开到周时间轴上的一段开放时间，单位为分钟。
319	// 周一 00:00 为起点 0。
320	type interval struct {
321		start int
322		end   int
323		label string
324	}
325	
326	// validateHours 检查所有时段是否相交或互相包含。
327	// 时段按“开始星期 × 开始时间”展开；跨午夜时段延伸到次日。
328	// 为检查周日延续到周一的情况，所有时段再复制一份到下一周坐标系。
329	// 前一段结束与下一段开始相同时允许保存。
330	func validateHours(hours []WeeklyHour) error {
331		intervals := make([]interval, 0, len(hours)*2)
332		for _, h := range hours {
333			startMin := minutes(h.Start)
334			endMin := minutes(h.End)
335			label := fmt.Sprintf("%s %s-%s", weekdayName(h.Weekday), h.Start, h.End)
336			if startMin == endMin {
337				return badRequest("开放时段无效：%s 的结束时间与开始时间相同", label)
338			}
339			start := (h.Weekday-1)*1440 + startMin
340			end := (h.Weekday-1)*1440 + endMin
341			if endMin < startMin {
342				end += 1440 // 跨午夜，次日结束
343			}
344			intervals = append(intervals, interval{start: start, end: end, label: label})
345		}
346		// 复制到下一周，用于检测周日跨午夜与下周一时段相交。
347		base := make([]interval, len(intervals))
348		copy(base, intervals)
349		for _, iv := range base {
350			intervals = append(intervals, interval{
351				start: iv.start + 7*1440,
352				end:   iv.end + 7*1440,
353				label: iv.label,
354			})
355		}
356		sort.Slice(intervals, func(i, j int) bool {
357			if intervals[i].start != intervals[j].start {
358				return intervals[i].start < intervals[j].start
359			}
360			return intervals[i].end < intervals[j].end
361		})
362		for i := 1; i < len(intervals); i++ {
363			if intervals[i].start < intervals[i-1].end {
364				return badRequest("开放时段存在相交：%s 与其他时段重叠", intervals[i].label)
365			}
366		}
367		return nil
368	}
369	
370	func weekdayName(weekday int) string {
371		return [...]string{"", "周一", "周二", "周三", "周四", "周五", "周六", "周日"}[weekday]
372	}
373	
374	// newID 生成非空、概率上唯一的记录标识。
375	func newID() string {
376		b := make([]byte, 16)
377		if _, err := rand.Read(b); err != nil {
378			// crypto/rand 失败极不寻常；退化为纳秒时间戳，仍保证非空且基本唯一。
379			return fmt.Sprintf("v-%d", time.Now().UnixNano())
380		}
381		return hex.EncodeToString(b)
382	}
383	
384	func idTaken(venues []Venue, id string) bool {
385		for _, v := range venues {
386			if v.ID == id {
387				return true
388			}
389		}
390		return false
391	}
